<template><div class="space-y-4"><el-input v-model="items" type="textarea" :rows="6" placeholder="输入抽签内容，每行一个"/><el-button size="small" type="primary" @click="draw">开始抽签</el-button><div v-if="result" class="rounded-xl bg-yellow-50 p-6 text-center text-2xl font-bold text-yellow-600 dark:bg-yellow-900/20">{{ result }}</div></div></template>
<script setup lang="ts">import { ref } from 'vue';const items=ref(''),result=ref('');const draw=()=>{const a=items.value.split(/[\n,，]+/).map(x=>x.trim()).filter(Boolean);result.value=a.length?a[Math.floor(Math.random()*a.length)]:'请先输入抽签内容'}</script>
